{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attached directly to a user",
      "resource": "aws_iam_user_policy_attachment.privesc3-passrole-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "The managed IAM policy is attached directly to an IAM user, increasing the risk of permissions being inadvertently retained or becoming difficult to audit. Assigning the user to a group and attaching the policy to that group provides more consistent access management."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc3-passrole-group" {
  name = "fn1-privesc3-partial-users"
}

resource "aws_iam_group_membership" "privesc3-passrole-group-membership" {
  name  = "fn1-privesc3-partial-user-membership"
  users = [aws_iam_user.fn1-privesc3-partial-user.name]
  group = aws_iam_group.privesc3-passrole-group.name
}

resource "aws_iam_group_policy_attachment" "privesc3-passrole-user-attach-policy" {
  group      = aws_iam_group.privesc3-passrole-group.name
  policy_arn = aws_iam_policy.fn1-passrole-star.arn
}
",
  "fix_summary": "Replaced the direct user policy attachment with a dedicated IAM group policy attachment and added the existing user to that group. The referenced managed policy remains unchanged."
}
